-- app_clinic_billing: members: [] — ноль членов в стационаре (SCHEME §C/§E).
DO $bcb$
DECLARE m record;
BEGIN
  FOR m IN SELECT pg_catalog.pg_get_userbyid(am.member) AS member
             FROM pg_catalog.pg_auth_members am
            WHERE am.roleid = 'app_clinic_billing'::regrole ORDER BY 1 LOOP
    EXECUTE pg_catalog.format('REVOKE %I FROM %I', 'app_clinic_billing', m.member);
