-- ─────────── 8. DEFINER-ИСКЛЮЧЕНИЯ: владелец + ACL (SCHEME §A.7/§B) ───────────
-- proconfig (SET search_path) НЕ эмитится: его применяет тело функции в миграции (§B).

-- SECURITY DEFINER has no fallback owner: every live signature must be declared exactly.
DO $bcb$
DECLARE f text;
BEGIN
  SELECT pg_catalog.format('%I.%I(%s)', n.nspname, p.proname,
           pg_catalog.replace(pg_catalog.pg_get_function_identity_arguments(p.oid), ', ', ',')) INTO f
    FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace
   WHERE p.prosecdef AND n.nspname IN ('app', 'app_ext')
     AND pg_catalog.format('%I.%I(%s)', n.nspname, p.proname, pg_catalog.replace(pg_catalog.pg_get_function_identity_arguments(p.oid), ', ', ',')) NOT IN ('app.clear_port_context()', 'app.current_actor_user_id()', 'app.current_integrator_user_id()', 'app.current_org_id()', 'app.current_patient_user_id()', 'app.install_port_context(uuid,app.port_context_claims)', 'app.require_accepted_context(name,name,app.port_context_class,text,bytea,regprocedure)', 'app.require_platform_principal()', 'app_ext.resolve_variant_a_identity(uuid)')
   LIMIT 1;
  IF f IS NOT NULL THEN RAISE EXCEPTION 'undeclared SECURITY DEFINER function: %', f; END IF;
END
